module FSMD(clk,in,reset,out,state,next_state);
	input clk,in,reset;
	output reg out;
	output [2:0] state,next_state;

	parameter idle=3'd0,start=3'd1,op1=3'd2,op2=3'd3,op3=3'd4,done=3'd5;

	always@(*)begin
		case(state)
			idle:begin
				if(in)begin
					next_state=start;
					out<=0;
				end
				else begin
					next_state=idle;
					out<=0;
				end
			end
			start:begin
				next_state=op1;
				out<=0;
			end
			op1:begin
				next_state=op2;
				out<=in;
			end
			op2:begin
				next_state=op3;
				out<=in;
			end
			op3:begin
				next_state=done;
				out<=in;
			end
			done:begin
				if(in)begin
					next_state=start;
					out<=0;
				end
				else begin
					next_state=idle;
					out<=0;
				end
			end
			default:next_state=idle;
		endcase
	end

	always@(posedge clk)begin
		if(reset)begin
			state<=idle;
		end
		else begin
			state<=next_state;
		end
	end
endmodule

