module shift_register (
	input clk,
	input in,
	input reset,
	output [7:0] out_byte,
	output done
);
	reg [7:0] shift_reg;

	always @ (posedge clk) begin
		if (reset) begin
			shift_reg <= 8'b0;
		end
		else begin
			shift_reg <= {in, shift_reg[7:1]};
		end
	end

	assign out_byte = shift_reg;
	assign done = &shift_reg;

endmodule

module fibonacci (
	input clk,
	input in,
	input reset,
	output reg [7:0] out_byte = 0,
	output reg done = 0
);
	reg [7:0] shift_reg;
	reg [7:0] count = 0;

	always @ (posedge clk) begin
		if (reset) begin
			shift_reg <= 8'b0;
			out_byte <= 8'b0;
			count <= 0;
			done <= 0;
		end
		else begin
			if (|shift_reg && &shift_reg) done <= 1'b1;
			else begin
				done <= 1'b0;
				shift_reg <= {in, shift_reg[7:1]};
				if (&shift_reg) out_byte <= shift_reg + 1;
				else out_byte <= shift_reg;
			end

			if (|shift_reg) count <= count + 1;
			else begin
				count <= 0;
				out_byte <= 0;
			end
		end
	end
endmodule

