module FSMD(clk, areset, bump_left, bump_right, ground, dig, state, next_state);
	input clk, areset, bump_left, bump_right, ground, dig;
	output reg [2:0] state, next_state;

	localparam S0 = 3'd0,
	           S1 = 3'd1,
				  S2 = 3'd2,
				  S3 = 3'd3,
				  S4 = 3'd4;

	always@(*)begin
		case(state)
			S0:begin
				if(ground==1 & dig==1)
					next_state <= S1;
				else if(ground==1 & bump_left==1)
					next_state <= S2;
				else if(ground==1 & bump_right==1)
					next_state <= S3;
				else
					next_state <= S0;
			end
			S1:next_state <= ground ? S1:S4;
			S2:next_state <= ground ? S2:S4;
			S3:next_state <= ground ? S3:S4;
			S4:begin
				if(ground==1 & dig==1)
					next_state <= S1;
				else if(ground==1 & bump_left==1)
					next_state <= S2;
				else if(ground==1 & bump_right==1)
					next_state <= S3;
				else
					next_state <= S0;
			end
			default:next_state <= S0;
		endcase
	end

	always@(posedge clk or posedge areset)begin
		if(areset==1)
			state <= S0;
		else
			state <= next_state;
	end
endmodule

