module Count4(clk, reset, q);
    parameter N = 4;
    input clk, reset;
    output[N-1:0] q;
    reg[N-1:0] q, q_next;

    always @(*) begin
        q_next <= reset ? {N{1'b0}} : q + {{(N-1){1'b0}}, 1'b1};
    end

    always @(posedge clk) begin
        q <= q_next;
    end
endmodule

module Shift_Register_N(clk, reset, parallel_load, shift_left, serial_in, parallel_in, enable, q, serial_out);
    parameter N = 4;
    input clk, reset, parallel_load, shift_left, enable, serial_in;
    input[N-1:0] parallel_in;
    output reg[N-1:0] q;
    output serial_out;

    assign serial_out = q[0];

    always @(posedge clk) begin
        if(reset)
            q <= {N{1'b0}};
        else if(parallel_load)
            q <= parallel_in;
        else if(enable & shift_left)
            q <= {serial_in, q[N-1:1]};
        else if(enable & ~shift_left)
            q <= {q[N-2:0], 1'b0};
    end
endmodule



