module FSM (
	input clk,
	input areset,
	input bump_left,
	input bump_right,
	output reg walk_left,
	output reg walk_right,
	output reg aaah
);
	localparam S0=3'd0,
			   S1=3'd1,
			   S2=3'd2,
			   S3=3'd3,
			   S4=3'd4;
	reg[2:0] present,next;
	always@ (posedge clk or posedge areset) begin
		if(areset) present <= S0;
		else present <= next;
	end
	always@ (*) begin
		walk_left=1'b0;
		walk_right=1'b0;
		aaah=1'b0;
		case(present)
			S0: begin
				if(bump_left) next=S1;
				else if(bump_right) next=S2;
				else next=S0;
			end S1: begin
				walk_left=1;
				if(~ground) next=S3;
				else next=S1;
			end S2: begin
				walk_right=1;
				if(~ground) next=S3;
				else next=S2;
			end S3: aaah=1;
			default next=S0;
		endcase
	end
endmodule

